def maximumXor(s, t):
    # Only the counts of ones and zeros in t matter
    ones = t.count('1')
    zeros = len(t) - ones

    result = []
    for ch in s:
        if ch == '0':
            # Want a 1 from t so that 0 XOR 1 = 1
            if ones > 0:
                ones -= 1
                result.append('1')
            else:
                zeros -= 1
                result.append('0')
        else:
            # ch == '1': want a 0 from t so that 1 XOR 0 = 1
            if zeros > 0:
                zeros -= 1
                result.append('1')
            else:
                ones -= 1
                result.append('0')

    return ''.join(result)
